{"research_date": "2026-09-10", "pairs": [{"pair_id": "conflict_313ef3924afc3e327a13f127", "claim_ids": ["claim_11ba56c8282db4bee3d942cb", "claim_eaf29f1f56e0634007226273"], "query_ids": ["q_63"], "claims": [{"claim_id": "claim_11ba56c8282db4bee3d942cb", "quote": "As a result, the total tariff on EU autos and auto parts subject to Section 232 tariffs under Proclamation 10908 is 15% or the normal/Most Favorable Nation (MFN) rate under the HTSUS, whichever is greater. This change is retroactive to August 1, 2025.", "url": "https://www.butzel.com/alert-us-implements-eu-trade-deal-reducing-tariffs-on-eu-autos-parts-and-eliminating-tariffs-on-certain-other-products", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "Section 232 tariffs under Proclamation 10908", "duty_rate": "15% or the normal/Most Favorable Nation (MFN) rate under the HTSUS, whichever is greater", "effective_date": "August 1, 2025"}}, {"claim_id": "claim_eaf29f1f56e0634007226273", "quote": "The agreement will see automobiles and many other imports taxed at 15 percent, instead of the 27.5 percent tariff that Trump had threatened to enact on August 1.", "url": "https://www.caranddriver.com/news/a65542782/us-european-union-trade-deal-car-tariffs", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "15 percent", "duty_rate": "27.5 percent", "effective_date": "August 1"}}]}, {"pair_id": "conflict_998a311cc24e088dd8e89694", "claim_ids": ["claim_2c9df26bebe51e8ecfdd00e0", "claim_d5774556731bdc30be0262bc"], "query_ids": ["q_63"], "claims": [{"claim_id": "claim_2c9df26bebe51e8ecfdd00e0", "quote": "For EU cars and parts, the tariff rate dropped to 15 from 25% effective August 1st.", "url": "https://www.youtube.com/watch?v=k35z0cI3h_k", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"effective_date": "August 1st"}}, {"claim_id": "claim_d5774556731bdc30be0262bc", "quote": "confirming that a 15% duty rate for EU autos and auto parts began on August 1.", "url": "https://www.youtube.com/watch?v=k35z0cI3h_k", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"duty_rate": "15%", "effective_date": "August 1"}}]}, {"pair_id": "conflict_9e9eedfd0479c0cad84c5073", "claim_ids": ["claim_6889d86f2750a42216df50fc", "claim_afb3bdece75f7d2d86b611fa"], "query_ids": ["q_64"], "claims": [{"claim_id": "claim_6889d86f2750a42216df50fc", "quote": "These measures follow Proclamation 10908, which imposed a 25% tariff on certain imported automobiles starting April 3, 2025, and parts beginning May 3, 2025", "url": "https://www.ghy.com/trade-compliance/new-tariff-relief-procedures-for-usmca-eligible-automobile-imports", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "Proclamation 10908", "duty_rate": "25%", "effective_date": "May 3, 2025"}}, {"claim_id": "claim_afb3bdece75f7d2d86b611fa", "quote": "The Proclamation imposed a 25 percent tariff on certain imports of automobiles, effective April 3, 2025, and certain imports of auto parts, effective May 3, 2025.", "url": "https://www.federalregister.gov/documents/2025/05/20/2025-08917/procedures-for-submissions-by-importers-of-automobiles-qualifying-for-preferential-tariff-treatment", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {"tariff_program": "Proclamation", "duty_rate": "25 percent", "effective_date": "May 3, 2025"}}]}, {"pair_id": "conflict_22eda470efe9b9799c807b26", "claim_ids": ["claim_049b6af867f270686e2a26ee", "claim_9c566896ab52b9747a1960d5"], "query_ids": ["q_69"], "claims": [{"claim_id": "claim_049b6af867f270686e2a26ee", "quote": "Electric vehicles (BEVs and PHEVs) | 25% | 100% | September 27, 2024", "url": "https://gingercontrol.com/blog/section-301-tariff-rates-china", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"affected_product": "Electric vehicles (BEVs and PHEVs)", "duty_rate": "100%", "effective_date": "September 27, 2024"}}, {"claim_id": "claim_9c566896ab52b9747a1960d5", "quote": "The tariff rate will increase from 25% to 100% on August 1, 2024 for certain fully electric passenger vehicles, as well as certain hybrid passenger vehicles that can be charged through plugging into an external power source.", "url": "https://www.wiley.law/alert-Administration-Releases-Details-on-Planned-Increases-to-Section-301-Duties-on-Imports-from-China", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "Office of the U.S. Trade Representative (USTR)", "tariff_program": "Section 301", "affected_product": "certain fully electric passenger vehicles, as well as certain hybrid passenger vehicles that can be charged through plugging into an external power source", "duty_rate": "100%", "effective_date": "August 1, 2024"}}]}, {"pair_id": "conflict_5cbe7e64621279fbd81efbdf", "claim_ids": ["claim_0f7ff76728bf26231de08c7d", "claim_557ee40e5cd3c02ebe650f5b"], "query_ids": ["q_71"], "claims": [{"claim_id": "claim_0f7ff76728bf26231de08c7d", "quote": "9903.94.06: Applies to all entries of articles classifiable under HTSUS provisions listed in subdivision (g) that are eligible for special tariff treatment under the United States-Mexico-Canada Agreement (USMCA), other than automobile knock-down kits or parts compilations; or that are not passenger vehicles (sedans, sport utility vehicles, crossover utility vehicles, minivans, and cargo vans) and light trucks. 0 percent additional ad valorem rate of duty", "url": "https://content.govdelivery.com/accounts/USDHSCBP/bulletins/3de7ef9", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"affected_product": "automobile knock-down kits or parts compilations", "duty_rate": "0 percent additional ad valorem rate of duty"}}, {"claim_id": "claim_557ee40e5cd3c02ebe650f5b", "quote": "Knock-down kits or other equivalent parts compilations will remain subject to the 25 percent tariff even if they meet USMCA requirements.", "url": "https://www.asashop.org/2025/10/22/new-tariffs-announced-on-medium-and-heavy-duty-vehicles-buses-and-parts", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "25 percent tariff", "affected_product": "Knock-down kits or other equivalent parts compilations"}}]}, {"pair_id": "conflict_ab57a13da468df6b0f539703", "claim_ids": ["claim_30b6e5ce859cddfbab725cfa", "claim_c553b18304e2441625e20897"], "query_ids": ["q_75"], "claims": [{"claim_id": "claim_30b6e5ce859cddfbab725cfa", "quote": "If the cable has any termination — crimped terminals, molded plugs, board-level headers — it classifies under 8544.42 (fitted with connectors). HS 8544.49 is for unterminated cable only.", "url": "https://wireharnessproduction.com/blog/cable-assembly-hs-code-guide", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {}}, {"claim_id": "claim_c553b18304e2441625e20897", "quote": "Most wire harnesses with connectors fall under HS 8544.30 (vehicle/transit vehicle/ship harnesses) or 8544.42 (other conductors ≤1,000 V with connectors).", "url": "https://wireharnessproduction.com/blog/cable-assembly-hs-code-guide", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {}}]}, {"pair_id": "conflict_79d18c907f132592136f1f39", "claim_ids": ["claim_3759878b201a76771c4fa2d7", "claim_537f842fbf537c29de47fddb"], "query_ids": ["q_75"], "claims": [{"claim_id": "claim_3759878b201a76771c4fa2d7", "quote": "The USMCA origin rule matters for companies that have shifted wire harness production to Mexico. If your Mexican facility sources Chinese wire but performs all cutting, stripping, crimping, and assembly in Mexico, the finished harness qualifies as Mexican-origin — eliminating both base duty and Section 301.", "url": "https://wireharnessproduction.com/blog/cable-assembly-hs-code-guide", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {}}, {"claim_id": "claim_537f842fbf537c29de47fddb", "quote": "facility sources Chinese wire but performs all cutting, stripping, crimping, and assembly in Mexico, the finished harness qualifies as Mexican-origin — eliminating both base duty and Section 301.", "url": "https://wireharnessproduction.com/blog/cable-assembly-hs-code-guide", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"country_of_origin": "Mexican-origin"}}]}, {"pair_id": "conflict_df8e68b74aa1168b262da0f1", "claim_ids": ["claim_20f9d000577e50a771046c42", "claim_3c53e6709b23cccb826cdf16"], "query_ids": ["q_76"], "claims": [{"claim_id": "claim_20f9d000577e50a771046c42", "quote": "Example: A Chinese brake rotor taxed at 25% steel tariff will not be taxed an additional 25% as an auto part", "url": "https://blogs.tradlinx.com/auto-tariffs-101-how-u-s-car-import-duties-really-work-in-2025", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"duty_rate": "25%"}}, {"claim_id": "claim_3c53e6709b23cccb826cdf16", "quote": "A 25% tariff applies to most imported auto parts, unless they are USMCA-compliant or fall under a specific exemption. This affects engines, electronics, brake systems, and more.", "url": "https://blogs.tradlinx.com/auto-tariffs-101-how-u-s-car-import-duties-really-work-in-2025", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "USMCA-compliant", "duty_rate": "25%"}}]}, {"pair_id": "conflict_17279725879b6d00f7eca3d3", "claim_ids": ["claim_20f9d000577e50a771046c42", "claim_904d156179d0538f71de0f5e"], "query_ids": ["q_76"], "claims": [{"claim_id": "claim_20f9d000577e50a771046c42", "quote": "Example: A Chinese brake rotor taxed at 25% steel tariff will not be taxed an additional 25% as an auto part", "url": "https://blogs.tradlinx.com/auto-tariffs-101-how-u-s-car-import-duties-really-work-in-2025", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"duty_rate": "25%"}}, {"claim_id": "claim_904d156179d0538f71de0f5e", "quote": "As of May 3, 2025, a 25% rate applies to non-exempt parts", "url": "https://blogs.tradlinx.com/auto-tariffs-101-how-u-s-car-import-duties-really-work-in-2025", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "non-exempt parts", "duty_rate": "25%", "effective_date": "May 3, 2025"}}]}, {"pair_id": "conflict_dde8e304fdb5d5ec3576007d", "claim_ids": ["claim_3c53e6709b23cccb826cdf16", "claim_904d156179d0538f71de0f5e"], "query_ids": ["q_76"], "claims": [{"claim_id": "claim_3c53e6709b23cccb826cdf16", "quote": "A 25% tariff applies to most imported auto parts, unless they are USMCA-compliant or fall under a specific exemption. This affects engines, electronics, brake systems, and more.", "url": "https://blogs.tradlinx.com/auto-tariffs-101-how-u-s-car-import-duties-really-work-in-2025", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "USMCA-compliant", "duty_rate": "25%"}}, {"claim_id": "claim_904d156179d0538f71de0f5e", "quote": "As of May 3, 2025, a 25% rate applies to non-exempt parts", "url": "https://blogs.tradlinx.com/auto-tariffs-101-how-u-s-car-import-duties-really-work-in-2025", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "non-exempt parts", "duty_rate": "25%", "effective_date": "May 3, 2025"}}]}]}

